//! Local registration → service assertion → access token flow. Host must persist state,
//! provision reviewed keys, authenticate claim sessions, and authorize requested scopes.
use crate::{
    claims::PendingClaim,
    token::{verify, verify_registration, Claims, Issuer, TokenState, Trust, ACCESS, ID_JAG},
    Error,
};
use rand_core::{OsRng, RngCore};
use serde::Serialize;
use std::collections::BTreeMap;

#[derive(Serialize)]
pub struct TokenResponse {
    pub access_token: String,
    pub token_type: String,
    pub expires_in: u32,
    pub scope: String,
}
#[derive(Serialize)]
pub struct Registration {
    pub registration_id: String,
    pub identity_assertion: String,
    pub assertion_expires: i64,
    pub scopes: Vec<String>,
}
struct Delegation {
    issuer: String,
    subject: String,
}
pub struct Service {
    issuer_url: String,
    resource: String,
    issuer: Issuer,
    trust: Trust,
    pub(crate) state: TokenState,
    delegations: BTreeMap<String, Delegation>,
}
fn nonce() -> String {
    let mut bytes = [0; 32];
    OsRng.fill_bytes(&mut bytes);
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
impl Service {
    pub fn new(
        issuer_url: String,
        resource: String,
        kid: String,
        key: ed25519_dalek::SigningKey,
    ) -> Self {
        let issuer = Issuer::new(issuer_url.clone(), kid.clone(), key);
        let trust = Trust {
            issuer: issuer_url.clone(),
            kid,
            key: issuer.public_key(),
            audience: issuer_url.clone(),
            client_id: "arkhe-auth-md".into(),
            max_lifetime: 600,
            max_auth_age: 3600,
        };
        Self {
            issuer_url,
            resource,
            issuer,
            trust,
            state: TokenState::default(),
            delegations: BTreeMap::new(),
        }
    }
    /// The scopes argument is trusted host policy, never copied from an agent request.
    /// This adapter uses an issuer+subject principal; it never links accounts by email.
    pub fn register_provider(
        &mut self,
        assertion: &str,
        provider: &Trust,
        now: i64,
        approved_scopes: &[String],
    ) -> Result<Registration, Error> {
        if provider.audience != self.issuer_url {
            return Err(Error::Untrusted);
        }
        let verified = verify_registration(assertion, provider, now, &mut self.state)?;
        let c = verified.claims();
        let subject = arkhe_core::Digest32::blake3(
            b"AKG:AUTH:PRINCIPAL:v1\0",
            &arkhe_core::canonical::encode_value(&serde_json::json!({"iss": c.iss, "sub": c.sub})),
        )
        .to_hex();
        self.mint(
            subject,
            c.email.clone(),
            c.auth_time,
            now,
            approved_scopes,
            c.iss.clone(),
            c.sub.clone(),
        )
    }
    pub fn register_claimed(
        &mut self,
        claim: &mut PendingClaim,
        verified_email: &str,
        now: i64,
        approved_scopes: &[String],
    ) -> Result<Registration, Error> {
        let subject = claim.take_subject(now)?;
        self.mint(
            subject.clone(),
            verified_email.into(),
            now,
            now,
            approved_scopes,
            self.issuer_url.clone(),
            subject,
        )
    }
    #[allow(clippy::too_many_arguments)]
    fn mint(
        &mut self,
        subject: String,
        email: String,
        auth_time: i64,
        now: i64,
        scopes: &[String],
        upstream_issuer: String,
        upstream_subject: String,
    ) -> Result<Registration, Error> {
        if !(0..=i64::MAX - 600).contains(&now)
            || !email.contains('@')
            || scopes.is_empty()
            || scopes
                .iter()
                .any(|s| s.is_empty() || s.chars().any(char::is_whitespace))
        {
            return Err(Error::InvalidToken);
        }
        let id = nonce();
        let claims = Claims {
            iss: self.issuer_url.clone(),
            sub: subject,
            aud: self.issuer_url.clone(),
            client_id: "arkhe-auth-md".into(),
            jti: nonce(),
            iat: now,
            exp: now + 600,
            auth_time,
            email,
            email_verified: true,
            scope: scopes.join(" "),
            registration_id: id.clone(),
        };
        let assertion = self.issuer.sign(&claims, ID_JAG)?;
        self.delegations.insert(
            id.clone(),
            Delegation {
                issuer: upstream_issuer,
                subject: upstream_subject,
            },
        );
        Ok(Registration {
            registration_id: id,
            identity_assertion: assertion,
            assertion_expires: claims.exp,
            scopes: scopes.to_vec(),
        })
    }
    pub fn exchange(
        &mut self,
        assertion: &str,
        resource: &str,
        now: i64,
    ) -> Result<TokenResponse, Error> {
        if resource != self.resource {
            return Err(Error::Untrusted);
        }
        let verified = verify(assertion, ID_JAG, &self.trust, now, &[], &mut self.state)?;
        if !self
            .delegations
            .contains_key(&verified.claims().registration_id)
        {
            return Err(Error::Untrusted);
        }
        let mut claims = verified.claims().clone();
        claims.aud = resource.into();
        claims.iat = now;
        claims.exp = now.saturating_add(300).min(claims.exp);
        claims.jti = nonce();
        Ok(TokenResponse {
            access_token: self.issuer.sign(&claims, ACCESS)?,
            token_type: "Bearer".into(),
            expires_in: (claims.exp - now) as u32,
            scope: claims.scope,
        })
    }
    pub fn revoke_token(&mut self, token: &str) {
        self.state.revoke_token(token);
    }
    /// Call only after verifying the upstream Security Event Token or an admin session.
    pub fn revoke_provider_subject(&mut self, issuer: &str, subject: &str) {
        for (id, delegation) in &self.delegations {
            if delegation.issuer == issuer && delegation.subject == subject {
                self.state.revoke_registration(&self.issuer_url, id);
            }
        }
    }
    pub fn access_trust(&self) -> Trust {
        Trust {
            audience: self.resource.clone(),
            max_lifetime: 300,
            issuer: self.trust.issuer.clone(),
            kid: self.trust.kid.clone(),
            key: self.trust.key,
            client_id: self.trust.client_id.clone(),
            max_auth_age: self.trust.max_auth_age,
        }
    }
    /// Resource server must consult the SAME revocation authority on every operation.
    pub fn token_state(&mut self) -> &mut TokenState {
        &mut self.state
    }
}

//! Strict Ed25519 JWT profile with caller-provisioned, issuer-bound keys.
use crate::Error;
use arkhe_core::Digest32;
use base64::{engine::general_purpose::URL_SAFE_NO_PAD as B64, Engine};
use ed25519_dalek::{Signature, Signer, SigningKey, VerifyingKey};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeSet, HashSet};

pub const ID_JAG: &str = "oauth-id-jag+jwt";
pub const ACCESS: &str = "at+jwt";

#[derive(Clone, Serialize, Deserialize)]
pub struct Claims {
    pub iss: String,
    pub sub: String,
    pub aud: String,
    pub client_id: String,
    pub jti: String,
    pub iat: i64,
    pub exp: i64,
    pub auth_time: i64,
    pub email: String,
    pub email_verified: bool,
    #[serde(default)]
    pub scope: String,
    /// Service-local delegation identifier, bound to all derived tokens.
    #[serde(default)]
    pub registration_id: String,
}
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Header {
    alg: String,
    typ: String,
    kid: String,
}

/// Secrets are deliberately not Debug/Serialize. Signer custody belongs to the host.
pub struct Issuer {
    issuer: String,
    kid: String,
    key: SigningKey,
}
impl Issuer {
    pub fn new(issuer: String, kid: String, key: SigningKey) -> Self {
        Self { issuer, kid, key }
    }
    pub fn public_key(&self) -> VerifyingKey {
        self.key.verifying_key()
    }
    pub fn sign(&self, claims: &Claims, typ: &str) -> Result<String, Error> {
        if claims.iss != self.issuer || ![ID_JAG, ACCESS].contains(&typ) {
            return Err(Error::Untrusted);
        }
        let header = Header {
            alg: "EdDSA".into(),
            typ: typ.into(),
            kid: self.kid.clone(),
        };
        let h = B64.encode(serde_json::to_vec(&header).map_err(|_| Error::InvalidToken)?);
        let c = B64.encode(serde_json::to_vec(claims).map_err(|_| Error::InvalidToken)?);
        let input = format!("{h}.{c}");
        Ok(format!(
            "{input}.{}",
            B64.encode(self.key.sign(input.as_bytes()).to_bytes())
        ))
    }
}

pub struct Trust {
    pub issuer: String,
    pub kid: String,
    pub key: VerifyingKey,
    pub audience: String,
    pub client_id: String,
    pub max_lifetime: i64,
    pub max_auth_age: i64,
}

/// Process-local reference state. A multi-process host must supply durable atomic state.
#[derive(Default)]
pub struct TokenState {
    seen: HashSet<(String, String)>,
    revoked_tokens: HashSet<Digest32>,
    revoked_registrations: HashSet<(String, String)>,
}
impl TokenState {
    pub fn revoke_token(&mut self, token: &str) {
        self.revoked_tokens.insert(token_digest(token));
    }
    /// Invoke only after authenticated administration or verified provider event delivery.
    pub fn revoke_registration(&mut self, issuer: &str, registration: &str) {
        self.revoked_registrations
            .insert((issuer.into(), registration.into()));
    }
}

/// Constructible only by successful signature/claims verification. Never serializes bearer data.
pub struct VerifiedToken {
    claims: Claims,
    digest: Digest32,
    typ: String,
}
impl VerifiedToken {
    pub fn claims(&self) -> &Claims {
        &self.claims
    }
    pub fn digest(&self) -> Digest32 {
        self.digest
    }
    pub fn is_access(&self) -> bool {
        self.typ == ACCESS
    }
}
pub fn token_digest(token: &str) -> Digest32 {
    Digest32::blake3(b"AKG:AUTH:TOKEN:v1\0", token.as_bytes())
}

pub fn verify(
    token: &str,
    typ: &str,
    trust: &Trust,
    now: i64,
    required_scopes: &[&str],
    state: &mut TokenState,
) -> Result<VerifiedToken, Error> {
    if token.len() > 16384 || ![ID_JAG, ACCESS].contains(&typ) {
        return Err(Error::InvalidToken);
    }
    let parts: Vec<_> = token.split('.').collect();
    if parts.len() != 3 {
        return Err(Error::InvalidToken);
    }
    let decode = |s: &str| B64.decode(s).map_err(|_| Error::InvalidToken);
    let header: Header =
        serde_json::from_slice(&decode(parts[0])?).map_err(|_| Error::InvalidToken)?;
    if header.alg != "EdDSA" || header.typ != typ || header.kid != trust.kid {
        return Err(Error::Untrusted);
    }
    let sig = Signature::from_slice(&decode(parts[2])?).map_err(|_| Error::InvalidToken)?;
    trust
        .key
        .verify_strict(format!("{}.{}", parts[0], parts[1]).as_bytes(), &sig)
        .map_err(|_| Error::InvalidToken)?;
    let claims: Claims =
        serde_json::from_slice(&decode(parts[1])?).map_err(|_| Error::InvalidToken)?;
    if claims.iss != trust.issuer
        || claims.aud != trust.audience
        || claims.client_id != trust.client_id
    {
        return Err(Error::Untrusted);
    }
    if now < 0
        || claims.iat < 0
        || claims.auth_time < 0
        || claims.iat > now
        || claims.exp <= now
        || claims.exp <= claims.iat
        || trust.max_lifetime <= 0
        || claims.exp - claims.iat > trust.max_lifetime
        || claims.auth_time > now
        || trust.max_auth_age <= 0
        || now - claims.auth_time > trust.max_auth_age
    {
        return Err(Error::Expired);
    }
    if claims.sub.is_empty()
        || claims.jti.is_empty()
        || (typ == ACCESS && claims.registration_id.is_empty())
        || !claims.email_verified
        || !claims.email.contains('@')
    {
        return Err(Error::InvalidToken);
    }
    let scopes: BTreeSet<_> = claims.scope.split_ascii_whitespace().collect();
    if required_scopes.iter().any(|s| !scopes.contains(s)) {
        return Err(Error::Scope);
    }
    let digest = token_digest(token);
    if state.revoked_tokens.contains(&digest)
        || state
            .revoked_registrations
            .contains(&(claims.iss.clone(), claims.registration_id.clone()))
    {
        return Err(Error::Revoked);
    }
    Ok(VerifiedToken {
        claims,
        digest,
        typ: typ.into(),
    })
}

/// Only provider registration consumes the ID-JAG. Service assertions may be re-exchanged.
pub fn verify_registration(
    token: &str,
    trust: &Trust,
    now: i64,
    state: &mut TokenState,
) -> Result<VerifiedToken, Error> {
    let verified = verify(token, ID_JAG, trust, now, &[], state)?;
    if !state
        .seen
        .insert((verified.claims.iss.clone(), verified.claims.jti.clone()))
    {
        return Err(Error::Replay);
    }
    Ok(verified)
}

//! AKG-CBOR-v1: RFC 8949 core deterministic encoding, definite lengths,
//! shortest integers, UTF-8 unchanged, byte digests, encoded-key ordered maps.
//! Unsigned projections contain all current fields (neither type has signatures).
use crate::{work::WorkIntent, worker::WorkerExecutionRecord, Digest32};
use serde_json::Value;

pub trait CanonicalEncode {
    const DOMAIN_OBJECT: &'static [u8];
    fn unsigned_projection(&self) -> Value;
    fn canonical_bytes(&self) -> Vec<u8> {
        encode(&self.unsigned_projection(), None)
    }
    fn object_digest(&self) -> Digest32 {
        Digest32::blake3(Self::DOMAIN_OBJECT, &self.canonical_bytes())
    }
}
fn head(major: u8, n: u64, out: &mut Vec<u8>) {
    let base = major << 5;
    match n {
        0..=23 => out.push(base | n as u8),
        24..=255 => out.extend([base | 24, n as u8]),
        256..=65535 => {
            out.push(base | 25);
            out.extend((n as u16).to_be_bytes());
        }
        65536..=4294967295 => {
            out.push(base | 26);
            out.extend((n as u32).to_be_bytes());
        }
        _ => {
            out.push(base | 27);
            out.extend(n.to_be_bytes());
        }
    }
}
pub fn encode_value(value: &Value) -> Vec<u8> {
    encode(value, None)
}

fn encode(v: &Value, field: Option<&str>) -> Vec<u8> {
    let mut out = Vec::new();
    match v {
        Value::Null => out.push(0xf6),
        Value::Bool(false) => out.push(0xf4),
        Value::Bool(true) => out.push(0xf5),
        Value::String(s) => {
            head(3, s.len() as u64, &mut out);
            out.extend(s.as_bytes());
        }
        Value::Number(n) => {
            if let Some(n) = n.as_u64() {
                head(0, n, &mut out);
            } else {
                head(
                    1,
                    (-1 - n.as_i64().expect("integer projection")) as u64,
                    &mut out,
                );
            }
        }
        Value::Array(a)
            if matches!(
                field,
                Some(
                    "hash"
                        | "target"
                        | "parameters_digest"
                        | "request_identity"
                        | "input_digest"
                        | "output_digest"
                        | "digest_element"
                        | "classification_digest"
                        | "policy_digest"
                )
            ) =>
        {
            head(2, a.len() as u64, &mut out);
            out.extend(a.iter().map(|v| v.as_u64().expect("digest byte") as u8));
        }
        Value::Array(a) => {
            head(4, a.len() as u64, &mut out);
            let child = if matches!(field, Some("context_refs" | "evidence_refs")) {
                Some("digest_element")
            } else {
                None
            };
            for v in a {
                out.extend(encode(v, child));
            }
        }
        Value::Object(m) => {
            let mut pairs: Vec<_> = m
                .iter()
                .map(|(k, v)| (encode(&Value::String(k.clone()), None), encode(v, Some(k))))
                .collect();
            pairs.sort_by(|a, b| a.0.cmp(&b.0));
            head(5, pairs.len() as u64, &mut out);
            for (k, v) in pairs {
                out.extend(k);
                out.extend(v);
            }
        }
    }
    out
}
impl CanonicalEncode for WorkIntent {
    const DOMAIN_OBJECT: &'static [u8] = b"AKG:WORKINTENT:v1\0";
    fn unsigned_projection(&self) -> Value {
        let mut projection = serde_json::json!({"requested_by": self.requested_by, "intent_type": self.intent_type, "target": self.target, "parameters_digest": self.parameters_digest, "context_refs": self.context_refs, "request_identity": self.request_identity, "claimed_created_at": self.claimed_created_at});
        if !self.context.is_empty() {
            projection["context"] = serde_json::to_value(&self.context).expect("typed context");
        }
        projection
    }
}
impl CanonicalEncode for WorkerExecutionRecord {
    const DOMAIN_OBJECT: &'static [u8] = b"AKG:WER:v1\0";
    fn unsigned_projection(&self) -> Value {
        let mut projection = serde_json::json!({"module_id": self.module_id, "module_version": self.module_version, "input_digest": self.input_digest, "output_digest": self.output_digest, "evidence_refs": self.evidence_refs, "confidence_bps": self.confidence_bps, "uncertainty_note": self.uncertainty_note, "execution_id": self.execution_id});
        if let Some(operation) = self.operation {
            projection["operation"] = serde_json::to_value(operation).expect("operation");
        }
        if let Some(binding) = self.classification {
            projection["classification"] =
                serde_json::to_value(binding).expect("classification binding");
        }
        projection
    }
}

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct Digest32(pub [u8; 32]);

impl Digest32 {
    pub const ZERO: Self = Self([0u8; 32]);

    pub fn blake3(domain: &[u8], payload: &[u8]) -> Self {
        let mut h = blake3::Hasher::new();
        h.update(domain);
        h.update(payload);
        Self(*h.finalize().as_bytes())
    }

    pub fn to_hex(self) -> String {
        self.0.iter().map(|b| format!("{b:02x}")).collect()
    }
}

use thiserror::Error;

#[derive(Debug, Error)]
pub enum CoreError {
    #[error("invalid input: {0}")]
    InvalidInput(String),
    #[error("evidence unavailable")]
    EvidenceUnavailable,
    #[error("authorization rejected: {0}")]
    AuthorizationRejected(String),
}

use crate::Digest32;
use async_trait::async_trait;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct EvidenceEnvelope {
    pub record_hash: Digest32,
    pub kind: String,
    pub subject: Digest32,
    pub payload_digest: Digest32,
    pub policy_digest: Option<Digest32>,
    pub causal_parents: Vec<Digest32>,
}

#[async_trait]
pub trait EvidenceReader: Send + Sync {
    async fn get(&self, record_hash: Digest32) -> Result<Option<EvidenceEnvelope>, String>;

    /// Opt-in untrusted transport. A required predicate with no proof fails closed.
    async fn formal_proof(
        &self,
        _worker_digest: Digest32,
    ) -> Result<Option<crate::formal_proof::ProofCarryingOutput>, String> {
        Ok(None)
    }

    /// Optional proof transport, keyed by the exact admitted WER. Returned bytes
    /// are untrusted: the kernel always checks the certificate independently.
    /// Stores without this capability fail closed for proof-requiring policies.
    async fn budget_proof(
        &self,
        _worker_digest: Digest32,
    ) -> Result<Option<crate::output_proof::BudgetProof>, String> {
        Ok(None)
    }
}

#[async_trait]
pub trait EvidenceCommitter: Send + Sync {
    async fn append_verified(&self, evidence: EvidenceEnvelope) -> Result<Digest32, String>;
}

/// A trusted admission boundary calls this only after authorization.
/// Implementations must commit both canonical objects and evidence atomically.
#[async_trait]
pub trait WorkEvidenceCommitter: Send + Sync {
    async fn commit_work(
        &self,
        intent: &crate::work::WorkIntent,
        worker: &crate::worker::WorkerExecutionRecord,
        evidence: EvidenceEnvelope,
    ) -> Result<Digest32, String>;
}

//! Data for opt-in transparent license and role-validated AP2 payment predicates.
//! Neither the data nor the producer grants authority. No ZK backend is implied.
use crate::{canonical::encode_value, Digest32};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};

pub fn commitment(domain: &[u8], value: &impl Serialize) -> Digest32 {
    Digest32::blake3(
        domain,
        &encode_value(&serde_json::to_value(value).expect("typed proof data")),
    )
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LicensePolicy {
    pub version: u16,
    /// Governance-authored semantics, not an obligation table supplied by SPDX.
    pub obligations: BTreeMap<String, BTreeSet<String>>,
    pub permitted_obligations: BTreeSet<String>,
    pub require_zk: bool,
}
impl LicensePolicy {
    pub fn digest(&self) -> Digest32 {
        commitment(b"AKG:LICENSE:POLICY:v1\0", self)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LicenseInput {
    pub spdx_json: String,
    pub artifact: Vec<u8>,
}
impl LicenseInput {
    pub fn digest(&self) -> Digest32 {
        commitment(b"AKG:LICENSE:INPUT:v1\0", self)
    }
    pub fn sbom_digest(&self) -> Digest32 {
        Digest32::blake3(b"AKG:LICENSE:SPDX:v1\0", self.spdx_json.as_bytes())
    }
    pub fn artifact_digest(&self) -> Digest32 {
        Digest32::blake3(b"AKG:LICENSE:ARTIFACT:v1\0", &self.artifact)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LicenseOutput {
    pub compatible: bool,
    pub sbom_digest: Digest32,
    pub artifact_digest: Digest32,
}
impl LicenseOutput {
    pub fn digest(&self) -> Digest32 {
        commitment(b"AKG:LICENSE:OUTPUT:v1\0", self)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LicenseProof {
    pub checker: String,
    pub policy_digest: Digest32,
    pub spec_digest: Digest32,
    pub intent_digest: Digest32,
    pub worker_digest: Digest32,
    pub input: LicenseInput,
    pub output: LicenseOutput,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "kind", content = "spec", deny_unknown_fields)]
pub enum FormalPredicate {
    License(LicensePolicy),
    PaymentMandate(PaymentPolicy),
}
impl FormalPredicate {
    pub fn digest(&self) -> Digest32 {
        commitment(b"AKG:FORMAL:SPEC:v1\0", self)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "kind", content = "proof", deny_unknown_fields)]
pub enum ProofCarryingOutput {
    License(Box<LicenseProof>),
    PaymentMandate(Box<PaymentProof>),
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "mode", deny_unknown_fields)]
pub enum Ap2Flow {
    Direct,
    Autonomous,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PaymentExecution {
    pub network: String,
    pub payee: String,
    pub currency: String,
    pub amount_minor: u64,
    pub instrument_digest: Digest32,
    pub checkout_sha256: [u8; 32],
}
impl PaymentExecution {
    pub fn digest(&self) -> Digest32 {
